module.exports = [
{ e: "🍿", art: { b: "🍿", s: ["🌽", "💧", "💨", "💥"], c: ["#7A3A0B", "#F0D04A"] },
pt: { h: "Era noite de cinema em casa, e o vovô colocou o milho de pipoca na panela. Nina e Leo ficaram olhando os grãos duros e amarelinhos. De repente: POC! POC, POC! Os grãos explodiram em flocos brancos e fofinhos. “Como um grão tão duro vira uma coisa tão macia?”, perguntou Leo.", t: "O segredo da pipoca", f: "Cada grão de milho de pipoca tem uma gotinha de água guardada dentro de uma casca muito dura. Quando o grão esquenta, essa água vira vapor, e o vapor precisa de muito mais espaço do que a água. A pressão aumenta, aumenta, até que a casca não aguenta e estoura! O amido de dentro se expande e endurece em forma de espuma: a pipoca.", x: "Pessoas já comiam pipoca há milhares de anos: arqueólogos encontraram grãos de pipoca muito antigos em cavernas e sítios nas Américas! O milho de pipoca é um tipo especial de milho, com a casca mais dura do que o milho comum.", s: ["Os grãos que não estouram geralmente têm a casca rachada ou água de menos.", "A pipoca pode pular porque o estouro empurra o grão para cima.", "Existem dois formatos principais de pipoca: a de “borboleta”, com asinhas, e a de “cogumelo”, redondinha."], ex: { t: "Pipoca de cientista", m: "milho de pipoca, uma panela com tampa, um pouquinho de óleo, um adulto no fogão", p: ["Antes de estourar, conte 20 grãos e observe: são duros, pequenos e brilhantes.", "Com um adulto, estoure a pipoca na panela tampada, sempre longe do fogão.", "Compare um grão estourado com um que não estourou. Conte quantos grãos sobraram sem estourar!"] }, at: "Ficha do laboratório nº 21", m: "caderno, lápis de cor, cola, pipocas", p: ["Desenhe o grão por dentro: a casca, a gotinha de água e o amido.", "Cole uma pipoca e um grão sem estourar no caderno, lado a lado.", "Escreva: “Água + calor = vapor que estoura a pipoca!”."], q: "Você prefere pipoca doce ou salgada? Que sabor novo inventaria?" },
en: { h: "It was movie night at home, and Grandpa put popcorn kernels in the pot. Nina and Leo stared at the hard little yellow kernels. Suddenly: POP! POP, POP! The kernels burst into fluffy white flakes. “How does such a hard kernel turn into something so soft?” Leo asked.", t: "The secret of popcorn", f: "Every popcorn kernel holds a tiny drop of water inside a very hard shell. When the kernel heats up, that water turns into steam, and steam needs much more space than water. The pressure builds and builds until the shell can't hold it and bursts! The starch inside expands and sets into a foam: popcorn.", x: "People have been eating popcorn for thousands of years: archaeologists have found very old popcorn kernels in caves and sites across the Americas! Popcorn is a special kind of corn with a harder shell than regular corn.", s: ["Kernels that don't pop usually have cracked shells or too little water.", "Popcorn can jump because the burst pushes the kernel upward.", "There are two main popcorn shapes: “butterfly,” with little wings, and “mushroom,” round and ball-like."], ex: { t: "Scientist's popcorn", m: "popcorn kernels, a pot with a lid, a little oil, a grown-up at the stove", p: ["Before popping, count 20 kernels and look closely: they're hard, small and shiny.", "With a grown-up, pop the popcorn in the covered pot, always staying away from the stove.", "Compare a popped kernel with one that didn't pop. Count how many kernels were left unpopped!"] }, at: "Lab card no. 21", m: "notebook, colored pencils, glue, popcorn", p: ["Draw the inside of a kernel: the shell, the drop of water and the starch.", "Glue a popped kernel and an unpopped one side by side in your notebook.", "Write: “Water + heat = steam that pops the corn!”"], q: "Do you like sweet or salty popcorn better? What new flavor would you invent?" },
es: { h: "Era noche de cine en casa, y el abuelo puso el maíz pisingallo en la olla. Nina y Leo miraban los granos duros y amarillitos. De repente: ¡POP! ¡POP, POP! Los granos explotaron en copos blancos y esponjosos. “¿Cómo un grano tan duro se convierte en algo tan suave?”, preguntó Leo.", t: "El secreto de los pochoclos", f: "Cada grano de maíz pisingallo tiene una gotita de agua guardada dentro de una cáscara muy dura. Cuando el grano se calienta, esa agua se convierte en vapor, y el vapor necesita mucho más espacio que el agua. La presión aumenta y aumenta, hasta que la cáscara no aguanta y ¡explota! El almidón de adentro se expande y se endurece en forma de espuma: el pochoclo.", x: "¡Las personas ya comían pochoclos hace miles de años: los arqueólogos encontraron granos muy antiguos en cuevas y sitios de América! El maíz pisingallo es un tipo especial de maíz, con la cáscara más dura que el maíz común.", s: ["Los granos que no explotan suelen tener la cáscara rajada o poca agua.", "El pochoclo puede saltar porque la explosión empuja el grano hacia arriba.", "Hay dos formas principales de pochoclo: la “mariposa”, con alitas, y la “hongo”, redondita."], ex: { t: "Pochoclos de científico", m: "maíz pisingallo, una olla con tapa, un poquito de aceite, un adulto en la cocina", p: ["Antes de hacerlos, cuenta 20 granos y obsérvalos: son duros, chiquitos y brillantes.", "Con un adulto, hagan los pochoclos en la olla tapada, siempre lejos de la hornalla.", "Compara un grano explotado con uno que no explotó. ¡Cuenta cuántos granos quedaron sin explotar!"] }, at: "Ficha del laboratorio nº 21", m: "cuaderno, lápices de colores, plasticola, pochoclos", p: ["Dibuja el grano por dentro: la cáscara, la gotita de agua y el almidón.", "Pega un pochoclo y un grano sin explotar en el cuaderno, uno al lado del otro.", "Escribe: “¡Agua + calor = vapor que hace explotar el maíz!”."], q: "¿Prefieres los pochoclos dulces o salados? ¿Qué sabor nuevo inventarías?" } },

{ e: "💧", art: { b: "💧", s: ["🧼", "🌈", "💨", "⚪"], c: ["#1B4A7A", "#C2A0F0"] },
pt: { h: "No quintal, Nina soprou uma bolha de sabão enorme, que flutuou brilhando com todas as cores do arco-íris. “Por que as bolhas são sempre redondas, mesmo quando o aro é quadrado?”, perguntou Leo, que tinha feito um aro de arame em forma de quadrado. O vovô sorriu: “Essa é uma das perguntas mais bonitas da química!”", t: "A química das bolhas de sabão", f: "Uma bolha de sabão é uma camada finíssima de água presa entre duas camadas de sabão, como um sanduíche. O sabão deixa a água mais elástica, e por isso ela consegue se esticar sem estourar. A bolha fica redonda porque a película puxa tudo para dentro igualmente, e a esfera é a forma que guarda o ar usando a menor quantidade de superfície.", x: "As cores das bolhas aparecem porque a luz reflete na parte de dentro e na parte de fora da película, e essas luzes se misturam. Quando a bolha fica escura em cima, é sinal de que está ficando fininha demais e vai estourar logo!", s: ["As bolhas duram mais em dias úmidos, porque a água evapora mais devagar.", "Um pouco de açúcar ou glicerina na mistura deixa as bolhas mais resistentes.", "Quando duas bolhas se juntam, a parede entre elas fica reta ou levemente curvada."], ex: { t: "Super bolhas", m: "1 xícara de água, 2 colheres de detergente, 1 colher de açúcar ou glicerina, arames ou canudos para fazer aros", p: ["Misture devagar a água, o detergente e o açúcar, sem fazer espuma. Deixe descansar por alguns minutos.", "Faça aros de formatos diferentes: redondo, quadrado, triângulo e estrela.", "Sopre bolhas com cada aro: elas sempre ficam redondas quando se soltam no ar! Molhe a mão na mistura e tente tocar numa bolha sem estourar."] }, at: "Ficha do laboratório nº 22", m: "caderno, lápis de cor", p: ["Desenhe os aros que você fez e as bolhas que saíram de cada um.", "Desenhe uma bolha por dentro: sabão, água e sabão.", "Conte e anote quanto tempo a sua maior bolha ficou no ar."], q: "Se você pudesse entrar numa bolha gigante, para onde flutuaria?" },
en: { h: "In the yard, Nina blew a huge soap bubble that floated away, shimmering with every color of the rainbow. “Why are bubbles always round, even when the wand is square?” asked Leo, who had made a square wand out of wire. Grandpa smiled: “That's one of the most beautiful questions in chemistry!”", t: "The chemistry of soap bubbles", f: "A soap bubble is a super-thin layer of water trapped between two layers of soap, like a sandwich. Soap makes the water stretchier, so it can stretch without popping. The bubble is round because the film pulls inward evenly in every direction, and a sphere is the shape that holds air using the least amount of surface.", x: "Bubble colors appear because light reflects off both the inside and the outside of the film, and those reflections mix together. When the top of a bubble turns dark, it means it's getting too thin and will pop soon!", s: ["Bubbles last longer on humid days because the water evaporates more slowly.", "A little sugar or glycerin in the mix makes bubbles stronger.", "When two bubbles join, the wall between them is flat or slightly curved."], ex: { t: "Super bubbles", m: "1 cup of water, 2 tablespoons of dish soap, 1 spoonful of sugar or glycerin, wire or straws to make wands", p: ["Gently mix the water, soap and sugar without making foam. Let it rest for a few minutes.", "Make wands in different shapes: circle, square, triangle and star.", "Blow bubbles with each wand: they always turn round once they float free! Wet your hand in the mix and try touching a bubble without popping it."] }, at: "Lab card no. 22", m: "notebook, colored pencils", p: ["Draw the wands you made and the bubbles that came out of each one.", "Draw a bubble's wall up close: soap, water and soap.", "Time and write down how long your biggest bubble stayed in the air."], q: "If you could climb into a giant bubble, where would you float to?" },
es: { h: "En el patio, Nina sopló una burbuja de jabón enorme, que flotó brillando con todos los colores del arcoíris. “¿Por qué las burbujas siempre son redondas, aunque el aro sea cuadrado?”, preguntó Leo, que había hecho un aro de alambre en forma de cuadrado. El abuelo sonrió: “¡Esa es una de las preguntas más lindas de la química!”", t: "La química de las burbujas de jabón", f: "Una burbuja de jabón es una capa finísima de agua atrapada entre dos capas de jabón, como un sándwich. El jabón hace que el agua sea más elástica, y por eso puede estirarse sin reventar. La burbuja es redonda porque la película tira hacia adentro igual en todas las direcciones, y la esfera es la forma que guarda el aire usando la menor cantidad de superficie.", x: "¡Los colores de las burbujas aparecen porque la luz se refleja en la parte de adentro y en la de afuera de la película, y esas luces se mezclan! Cuando la burbuja se pone oscura arriba, es señal de que se está volviendo demasiado fina y va a reventar pronto.", s: ["Las burbujas duran más en los días húmedos, porque el agua se evapora más despacio.", "Un poco de azúcar o glicerina en la mezcla hace que las burbujas sean más resistentes.", "Cuando dos burbujas se juntan, la pared entre ellas queda recta o apenas curvada."], ex: { t: "Súper burbujas", m: "1 taza de agua, 2 cucharadas de detergente, 1 cucharada de azúcar o glicerina, alambres o sorbetes para hacer aros", p: ["Mezcla despacio el agua, el detergente y el azúcar, sin hacer espuma. Déjalo descansar unos minutos.", "Haz aros de formas distintas: redondo, cuadrado, triángulo y estrella.", "Sopla burbujas con cada aro: ¡siempre quedan redondas cuando se sueltan en el aire! Moja la mano en la mezcla e intenta tocar una burbuja sin reventarla."] }, at: "Ficha del laboratorio nº 22", m: "cuaderno, lápices de colores", p: ["Dibuja los aros que hiciste y las burbujas que salieron de cada uno.", "Dibuja la pared de una burbuja de cerca: jabón, agua y jabón.", "Cronometra y anota cuánto tiempo estuvo en el aire tu burbuja más grande."], q: "Si pudieras meterte en una burbuja gigante, ¿hacia dónde flotarías?" } },

{ e: "🍍", art: { b: "🍍", s: ["🍮", "🥫", "✂️", "🔬"], c: ["#5A6B1B", "#F0C83A"] },
pt: { h: "Para a festa de aniversário, Nina quis fazer gelatina com pedaços de abacaxi fresco. Mas, no dia seguinte, a gelatina estava mole e líquida! Leo, por outro lado, tinha usado abacaxi em lata, e a gelatina dele ficou firme. “Será que o abacaxi fresco tem algum segredo?”, perguntou Nina.", t: "O abacaxi que desmancha a gelatina", f: "A gelatina fica firme porque é feita de uma proteína chamada colágeno, que forma uma rede que segura a água. O abacaxi fresco tem uma enzima chamada bromelina, que funciona como uma tesoura minúscula: ela corta essa rede de proteínas, e a gelatina não consegue endurecer. No abacaxi em lata, o calor do cozimento já desligou a enzima, e por isso a gelatina firma.", x: "A bromelina é tão boa em cortar proteínas que é usada para amaciar carnes! É por isso também que, às vezes, a língua fica um pouco sensível ou “pinicando” quando comemos muito abacaxi fresco: a enzima está trabalhando nas proteínas da boca.", s: ["O kiwi, o mamão e a manga fresca também têm enzimas que atrapalham a gelatina.", "As enzimas são proteínas que aceleram reações, e o nosso corpo tem milhares delas.", "O calor desliga a maioria das enzimas, como acontece no abacaxi cozido."], ex: { t: "Gelatina contra o abacaxi", m: "gelatina em pó preparada por um adulto, 3 copinhos, pedaços de abacaxi fresco, abacaxi em lata ou cozido, geladeira", p: ["Com um adulto, prepare a gelatina e divida em 3 copinhos.", "No primeiro, coloque abacaxi fresco; no segundo, abacaxi em lata; deixe o terceiro sem fruta.", "Leve à geladeira por algumas horas e compare: qual copinho ficou mole? Qual ficou firme?"] }, at: "Ficha do laboratório nº 23", m: "caderno, lápis de cor", p: ["Desenhe os 3 copinhos depois da geladeira e escreva o que aconteceu em cada um.", "Desenhe a bromelina como uma tesourinha cortando a rede da gelatina.", "Escreva: “O calor desliga a enzima do abacaxi”."], q: "Que outras frutas você testaria na gelatina para ver se ela firma?" },
en: { h: "For a birthday party, Nina wanted to make gelatin with chunks of fresh pineapple. But the next day, her gelatin was soft and runny! Leo, on the other hand, had used canned pineapple, and his gelatin set firmly. “Does fresh pineapple have some kind of secret?” Nina asked.", t: "The pineapple that melts gelatin", f: "Gelatin sets because it's made of a protein called collagen, which forms a net that holds the water. Fresh pineapple contains an enzyme called bromelain, which works like tiny scissors: it snips that protein net, so the gelatin can't set. In canned pineapple, the heat from cooking has already switched the enzyme off, so the gelatin sets.", x: "Bromelain is so good at cutting proteins that it's used to tenderize meat! That's also why your tongue sometimes feels a little tingly or sore when you eat lots of fresh pineapple: the enzyme is working on the proteins in your mouth.", s: ["Fresh kiwi, papaya and mango also have enzymes that interfere with gelatin.", "Enzymes are proteins that speed up reactions, and our bodies have thousands of them.", "Heat switches off most enzymes, as happens with cooked pineapple."], ex: { t: "Gelatin versus pineapple", m: "gelatin prepared by a grown-up, 3 small cups, chunks of fresh pineapple, canned or cooked pineapple, a fridge", p: ["With a grown-up, prepare the gelatin and divide it into 3 small cups.", "In the first, add fresh pineapple; in the second, canned pineapple; leave the third without fruit.", "Put them in the fridge for a few hours and compare: which cup stayed runny? Which set firmly?"] }, at: "Lab card no. 23", m: "notebook, colored pencils", p: ["Draw the 3 cups after the fridge and write what happened in each one.", "Draw bromelain as tiny scissors cutting the gelatin's net.", "Write: “Heat switches off the pineapple's enzyme.”"], q: "What other fruits would you test in gelatin to see if it sets?" },
es: { h: "Para la fiesta de cumpleaños, Nina quiso hacer gelatina con trocitos de ananá fresco. Pero, al día siguiente, ¡la gelatina estaba blanda y líquida! Leo, en cambio, había usado ananá en lata, y su gelatina quedó firme. “¿El ananá fresco tendrá algún secreto?”, preguntó Nina.", t: "El ananá que deshace la gelatina", f: "La gelatina se pone firme porque está hecha de una proteína llamada colágeno, que forma una red que sostiene el agua. El ananá fresco tiene una enzima llamada bromelina, que funciona como una tijera diminuta: corta esa red de proteínas, y la gelatina no puede endurecerse. En el ananá en lata, el calor de la cocción ya apagó la enzima, y por eso la gelatina se pone firme.", x: "¡La bromelina es tan buena cortando proteínas que se usa para ablandar carnes! Por eso también, a veces, la lengua queda un poco sensible o con cosquillas cuando comemos mucho ananá fresco: la enzima está trabajando en las proteínas de la boca.", s: ["El kiwi, la papaya y el mango frescos también tienen enzimas que arruinan la gelatina.", "Las enzimas son proteínas que aceleran reacciones, y nuestro cuerpo tiene miles de ellas.", "El calor apaga la mayoría de las enzimas, como pasa con el ananá cocido."], ex: { t: "Gelatina contra el ananá", m: "gelatina preparada por un adulto, 3 vasitos, trocitos de ananá fresco, ananá en lata o cocido, heladera", p: ["Con un adulto, preparen la gelatina y repártanla en 3 vasitos.", "En el primero, pon ananá fresco; en el segundo, ananá en lata; deja el tercero sin fruta.", "Llévalos a la heladera unas horas y compara: ¿qué vasito quedó blando? ¿Cuál quedó firme?"] }, at: "Ficha del laboratorio nº 23", m: "cuaderno, lápices de colores", p: ["Dibuja los 3 vasitos después de la heladera y escribe qué pasó en cada uno.", "Dibuja la bromelina como una tijerita cortando la red de la gelatina.", "Escribe: “El calor apaga la enzima del ananá”."], q: "¿Qué otras frutas probarías en la gelatina para ver si se pone firme?" } },

{ e: "🍞", art: { b: "🍞", s: ["👅", "🍬", "⏱️", "🦷"], c: ["#6B4A1B", "#F0C88A"] },
pt: { h: "No café da manhã, o vovô propôs um desafio estranho: “Mastiguem um pedacinho de pão sem engolir, devagar, por um minuto inteiro.” Nina e Leo mastigaram, mastigaram… e, de repente, Leo arregalou os olhos: “Ei! O pão ficou docinho!” O vovô riu: “Vocês acabaram de ver uma enzima trabalhando dentro da boca!”", t: "A química dentro da boca", f: "O pão é feito principalmente de amido, que é formado por muitos açúcares grudados em longas correntes. Por isso, o amido não tem gosto doce. A nossa saliva tem uma enzima chamada amilase, que corta essas correntes em pedaços menores de açúcar. Quanto mais tempo mastigamos, mais açúcar aparece, e o pão começa a ficar adocicado!", x: "A digestão começa na boca, antes mesmo de engolirmos! A saliva amolece a comida, começa a quebrar o amido e ajuda a engolir. Uma pessoa produz, em média, de meio litro a mais de um litro de saliva por dia.", s: ["A batata, o arroz e o macarrão também são ricos em amido.", "Mastigar bem ajuda o corpo a digerir melhor a comida.", "O cheiro de comida gostosa pode fazer a boca “encher de água”, produzindo mais saliva."], ex: { t: "O pão que fica doce", m: "um pedacinho de pão branco sem casca, um relógio ou cronômetro", p: ["Coloque o pedacinho de pão na boca e preste atenção no sabor: é doce?", "Mastigue devagar, sem engolir, por 1 minuto, misturando bem com a saliva.", "Preste atenção de novo: o sabor mudou? Muitas pessoas sentem o pão mais docinho no final!"] }, at: "Ficha do laboratório nº 24", m: "caderno, lápis de cor", p: ["Desenhe uma corrente de amido sendo cortada pela amilase em pedacinhos de açúcar.", "Faça uma lista de 5 alimentos ricos em amido.", "Desenhe o caminho da comida: boca, garganta e estômago."], q: "Você mastiga a comida bem devagar ou bem rápido? Que tal testar contar as mastigadas?" },
en: { h: "At breakfast, Grandpa proposed a strange challenge: “Chew a little piece of bread without swallowing, slowly, for one whole minute.” Nina and Leo chewed and chewed… and suddenly Leo's eyes went wide: “Hey! The bread tastes sweet!” Grandpa laughed: “You just saw an enzyme at work inside your mouth!”", t: "Chemistry inside your mouth", f: "Bread is made mostly of starch, which is made of many sugars linked together in long chains. That's why starch doesn't taste sweet. Our saliva has an enzyme called amylase, which cuts those chains into smaller sugar pieces. The longer we chew, the more sugar appears, and the bread starts tasting sweeter!", x: "Digestion starts in the mouth, even before we swallow! Saliva softens food, starts breaking down starch and helps us swallow. On average, a person makes from about half a liter to more than a liter of saliva a day.", s: ["Potatoes, rice and pasta are also rich in starch.", "Chewing well helps your body digest food better.", "The smell of tasty food can make your mouth “water,” producing more saliva."], ex: { t: "The bread that turns sweet", m: "a small piece of white bread without crust, a clock or timer", p: ["Put the piece of bread in your mouth and notice the taste: is it sweet?", "Chew slowly, without swallowing, for 1 minute, mixing it well with saliva.", "Notice again: did the taste change? Many people find the bread tastes sweeter at the end!"] }, at: "Lab card no. 24", m: "notebook, colored pencils", p: ["Draw a starch chain being cut by amylase into little pieces of sugar.", "Make a list of 5 foods rich in starch.", "Draw the path food takes: mouth, throat and stomach."], q: "Do you chew your food really slowly or really fast? Why not try counting your chews?" },
es: { h: "En el desayuno, el abuelo propuso un desafío raro: “Mastiquen un pedacito de pan sin tragarlo, despacio, durante un minuto entero.” Nina y Leo masticaron y masticaron… y, de repente, Leo abrió grandes los ojos: “¡Eh! ¡El pan se puso dulcecito!” El abuelo se rió: “¡Acaban de ver una enzima trabajando dentro de la boca!”", t: "La química dentro de la boca", f: "El pan está hecho principalmente de almidón, que está formado por muchos azúcares unidos en largas cadenas. Por eso, el almidón no tiene sabor dulce. Nuestra saliva tiene una enzima llamada amilasa, que corta esas cadenas en pedazos más chicos de azúcar. ¡Cuanto más tiempo masticamos, más azúcar aparece, y el pan empieza a ponerse dulzón!", x: "¡La digestión empieza en la boca, incluso antes de tragar! La saliva ablanda la comida, empieza a romper el almidón y ayuda a tragar. Una persona produce, en promedio, de medio litro a más de un litro de saliva por día.", s: ["La papa, el arroz y los fideos también son ricos en almidón.", "Masticar bien ayuda al cuerpo a digerir mejor la comida.", "El olor de una comida rica puede hacer que “se nos haga agua la boca”, produciendo más saliva."], ex: { t: "El pan que se vuelve dulce", m: "un pedacito de pan blanco sin corteza, un reloj o cronómetro", p: ["Pon el pedacito de pan en la boca y presta atención al sabor: ¿es dulce?", "Mastica despacio, sin tragar, durante 1 minuto, mezclándolo bien con la saliva.", "Presta atención otra vez: ¿cambió el sabor? ¡Muchas personas sienten el pan más dulce al final!"] }, at: "Ficha del laboratorio nº 24", m: "cuaderno, lápices de colores", p: ["Dibuja una cadena de almidón siendo cortada por la amilasa en pedacitos de azúcar.", "Haz una lista de 5 alimentos ricos en almidón.", "Dibuja el camino de la comida: boca, garganta y estómago."], q: "¿Masticas la comida muy despacio o muy rápido? ¿Y si pruebas contar las masticadas?" } },

{ e: "🌋", art: { b: "🥤", s: ["🍬", "💥", "⛲", "💧"], c: ["#3A1B1B", "#E07A4A"] },
pt: { h: "No parque, o vovô levou uma garrafa grande de refrigerante e um pacotinho de balas de menta. “Hoje vamos fazer um gêiser!”, anunciou. Todos se afastaram, o vovô soltou as balas dentro da garrafa e correu. FSSSHHHH! Um jato de espuma subiu bem alto, mais alto que a cabeça dele! Nina e Leo aplaudiram, molhados de tanto rir.", t: "O gêiser de refrigerante", f: "O refrigerante tem muito gás carbônico dissolvido, que é o que forma as bolhinhas. Esse gás precisa de um lugar para começar a formar bolhas. A superfície das balas de menta é cheia de buraquinhos microscópicos, que são lugares perfeitos para as bolhas nascerem. Assim, milhões de bolhas se formam de uma vez só e empurram o refrigerante para fora num jato!", x: "Essa não é uma reação química de verdade, mas sim uma mudança física: o gás que já estava no refrigerante só escapa de uma vez. O refrigerante diet costuma fazer um jato maior, e as balas também afundam rápido, liberando bolhas por toda a garrafa.", s: ["Os gêiseres de verdade são jatos de água quente e vapor que saem da terra.", "O refrigerante gelado faz um jato menor que o refrigerante em temperatura ambiente.", "É por isso que um refrigerante chacoalhado espirra quando abrimos a garrafa."], ex: { t: "Gêiser no parque", m: "uma garrafa de 2 litros de refrigerante diet, um pacote de balas de menta tipo Mentos, uma folha de papel enrolada em tubo, um lugar aberto, um adulto", p: ["Num lugar aberto, longe de pessoas e carros, coloque a garrafa em pé no chão e tire a tampa.", "Com um adulto, coloque as balas no tubo de papel, segurando a ponta de baixo com um cartão.", "O adulto posiciona o tubo sobre a garrafa, solta todas as balas de uma vez e todo mundo se afasta rápido! Observe a altura do jato."] }, at: "Ficha do laboratório nº 25", m: "caderno, lápis de cor", p: ["Desenhe o gêiser e marque a altura que ele chegou.", "Desenhe uma bala de menta bem de perto, cheia de buraquinhos com bolhas nascendo.", "Escreva: “O gás estava escondido no refrigerante!”."], q: "Você acha que um refrigerante quente faria um jato maior ou menor? Por quê?" },
en: { h: "At the park, Grandpa brought a big bottle of soda and a pack of mint candies. “Today we're making a geyser!” he announced. Everyone stepped back, Grandpa dropped the candies into the bottle and ran. FSSSHHHH! A jet of foam shot up high, higher than his head! Nina and Leo cheered, soaked from laughing so hard.", t: "The soda geyser", f: "Soda has lots of carbon dioxide gas dissolved in it, which is what makes the bubbles. That gas needs a place to start forming bubbles. The surface of mint candies is covered in microscopic pits, which are perfect places for bubbles to form. So millions of bubbles form all at once and push the soda out in a jet!", x: "This isn't really a chemical reaction but a physical change: gas that was already in the soda escapes all at once. Diet soda usually makes a bigger jet, and the candies also sink fast, releasing bubbles all through the bottle.", s: ["Real geysers are jets of hot water and steam that shoot out of the ground.", "Cold soda makes a smaller jet than room-temperature soda.", "That's why shaken soda sprays when you open the bottle."], ex: { t: "Park geyser", m: "a 2-liter bottle of diet soda, a pack of Mentos-type mint candies, a sheet of paper rolled into a tube, an open space, a grown-up", p: ["In an open space, away from people and cars, stand the bottle on the ground and take off the cap.", "With a grown-up, load the candies into the paper tube, holding the bottom end closed with a card.", "The grown-up holds the tube over the bottle, drops all the candies at once and everyone steps back fast! Watch how high the jet goes."] }, at: "Lab card no. 25", m: "notebook, colored pencils", p: ["Draw the geyser and mark how high it went.", "Draw a mint candy up close, covered in tiny pits with bubbles forming.", "Write: “The gas was hiding in the soda!”"], q: "Do you think warm soda would make a bigger or smaller jet? Why?" },
es: { h: "En el parque, el abuelo llevó una botella grande de gaseosa y un paquetito de caramelos de menta. “¡Hoy vamos a hacer un géiser!”, anunció. Todos se alejaron, el abuelo soltó los caramelos dentro de la botella y salió corriendo. ¡FSSSHHHH! Un chorro de espuma subió bien alto, ¡más alto que su cabeza! Nina y Leo aplaudieron, empapados de tanto reírse.", t: "El géiser de gaseosa", f: "La gaseosa tiene mucho gas carbónico disuelto, que es lo que forma las burbujitas. Ese gas necesita un lugar para empezar a formar burbujas. La superficie de los caramelos de menta está llena de agujeritos microscópicos, que son lugares perfectos para que nazcan las burbujas. ¡Así, millones de burbujas se forman de una sola vez y empujan la gaseosa hacia afuera en un chorro!", x: "Esta no es una reacción química de verdad, sino un cambio físico: el gas que ya estaba en la gaseosa solo escapa de una vez. La gaseosa dietética suele hacer un chorro más grande, y los caramelos además se hunden rápido, liberando burbujas por toda la botella.", s: ["Los géiseres de verdad son chorros de agua caliente y vapor que salen de la tierra.", "La gaseosa helada hace un chorro más chico que la gaseosa a temperatura ambiente.", "Por eso una gaseosa sacudida salpica cuando abrimos la botella."], ex: { t: "Géiser en el parque", m: "una botella de 2 litros de gaseosa dietética, un paquete de caramelos de menta tipo Mentos, una hoja de papel enrollada en tubo, un lugar abierto, un adulto", p: ["En un lugar abierto, lejos de personas y autos, pon la botella parada en el piso y sácale la tapa.", "Con un adulto, pongan los caramelos en el tubo de papel, sosteniendo la punta de abajo con una tarjeta.", "El adulto pone el tubo sobre la botella, suelta todos los caramelos de una vez y ¡todos se alejan rápido! Observa la altura del chorro."] }, at: "Ficha del laboratorio nº 25", m: "cuaderno, lápices de colores", p: ["Dibuja el géiser y marca la altura que alcanzó.", "Dibuja un caramelo de menta de cerca, lleno de agujeritos con burbujas naciendo.", "Escribe: “¡El gas estaba escondido en la gaseosa!”."], q: "¿Crees que una gaseosa caliente haría un chorro más grande o más chico? ¿Por qué?" } },

{ e: "🕯️", art: { b: "🕯️", s: ["🔥", "💨", "🍯", "⏱️"], c: ["#2A1B3A", "#F0A03A"] },
pt: { h: "Numa noite sem luz, o vovô acendeu uma vela na mesa. Leo perguntou: “Por que, quando a gente sopra, a chama apaga, mas quando a gente abana a lareira, o fogo cresce?” O vovô pensou um pouco e disse: “Porque o fogo é uma reação química que precisa de três coisas. Vou mostrar com um pote de vidro.”", t: "O fogo precisa de ar", f: "O fogo é uma reação química chamada combustão, que precisa de três coisas ao mesmo tempo: um combustível (como a cera da vela ou a madeira), calor e oxigênio. Se tirarmos qualquer uma delas, o fogo apaga. Quando cobrimos uma vela com um pote, ela usa o oxigênio que está dentro, e a chama vai diminuindo até se apagar.", x: "Os bombeiros usam esse “triângulo do fogo” para apagar incêndios: a água esfria (tira o calor), os cobertores e a areia abafam (tiram o oxigênio) e, às vezes, tiram o que pode queimar do caminho do fogo. Um sopro forte apaga a vela porque empurra a chama para longe do pavio.", s: ["A chama da vela é mais quente na parte de fora, perto da ponta azul.", "Na vela, é o vapor da cera que queima, não a cera sólida.", "Nunca brinque com fogo sem um adulto por perto."], ex: { t: "A vela no pote", m: "uma vela pequena e baixa num pires, um pote de vidro grande, um adulto para acender e cuidar da vela", p: ["O adulto acende a vela e coloca no pires, longe de papéis e cortinas.", "O adulto cobre a vela com o pote de vidro. Observe com atenção a chama.", "A chama vai diminuindo até apagar, porque o oxigênio dentro do pote acabou! Se tiver dois potes de tamanhos diferentes, compare: em qual a chama dura mais?"] }, at: "Ficha do laboratório nº 26", m: "caderno, lápis de cor", p: ["Desenhe o triângulo do fogo com combustível, calor e oxigênio em cada ponta.", "Desenhe a vela antes e depois de ser coberta pelo pote.", "Com a família, combine as regras de segurança com fogo da sua casa e escreva-as."], q: "Por que você acha que é tão importante ter um adulto por perto quando há fogo?" },
en: { h: "On a night when the power was out, Grandpa lit a candle on the table. Leo asked: “Why does a candle go out when we blow on it, but a fireplace fire grows when we fan it?” Grandpa thought for a moment and said: “Because fire is a chemical reaction that needs three things. I'll show you with a glass jar.”", t: "Fire needs air", f: "Fire is a chemical reaction called combustion, which needs three things at the same time: fuel (like candle wax or wood), heat and oxygen. If we take away any one of them, the fire goes out. When we cover a candle with a jar, it uses up the oxygen inside, and the flame shrinks until it goes out.", x: "Firefighters use this “fire triangle” to put out fires: water cools things down (removing heat), blankets and sand smother the fire (removing oxygen) and sometimes they clear away anything that could burn. A strong puff of breath blows a candle out because it pushes the flame away from the wick.", s: ["A candle flame is hottest on the outside, near the blue tip.", "In a candle, it's the wax vapor that burns, not the solid wax.", "Never play with fire without a grown-up nearby."], ex: { t: "Candle in a jar", m: "a small, short candle on a saucer, a large glass jar, a grown-up to light and watch the candle", p: ["The grown-up lights the candle and places it on the saucer, away from paper and curtains.", "The grown-up covers the candle with the glass jar. Watch the flame closely.", "The flame shrinks until it goes out, because the oxygen in the jar ran out! If you have two jars of different sizes, compare: in which one does the flame last longer?"] }, at: "Lab card no. 26", m: "notebook, colored pencils", p: ["Draw the fire triangle with fuel, heat and oxygen at each corner.", "Draw the candle before and after it was covered with the jar.", "With your family, agree on your home's fire safety rules and write them down."], q: "Why do you think it's so important to have a grown-up nearby when there's fire?" },
es: { h: "Una noche que se cortó la luz, el abuelo encendió una vela en la mesa. Leo preguntó: “¿Por qué, cuando soplamos, la llama se apaga, pero cuando abanicamos la chimenea, el fuego crece?” El abuelo pensó un poco y dijo: “Porque el fuego es una reacción química que necesita tres cosas. Te lo voy a mostrar con un frasco de vidrio.”", t: "El fuego necesita aire", f: "El fuego es una reacción química llamada combustión, que necesita tres cosas al mismo tiempo: un combustible (como la cera de la vela o la madera), calor y oxígeno. Si sacamos cualquiera de ellas, el fuego se apaga. Cuando tapamos una vela con un frasco, usa el oxígeno que hay adentro, y la llama va achicándose hasta apagarse.", x: "¡Los bomberos usan este “triángulo del fuego” para apagar incendios: el agua enfría (saca el calor), las mantas y la arena sofocan (sacan el oxígeno) y, a veces, apartan del camino del fuego lo que puede quemarse! Un soplido fuerte apaga la vela porque empuja la llama lejos de la mecha.", s: ["La llama de la vela es más caliente en la parte de afuera, cerca de la punta azul.", "En la vela, lo que se quema es el vapor de la cera, no la cera sólida.", "Nunca juegues con fuego sin un adulto cerca."], ex: { t: "La vela en el frasco", m: "una vela chica y baja en un platito, un frasco de vidrio grande, un adulto para encender y cuidar la vela", p: ["El adulto enciende la vela y la pone en el platito, lejos de papeles y cortinas.", "El adulto tapa la vela con el frasco de vidrio. Observa con atención la llama.", "¡La llama se va achicando hasta apagarse, porque se acabó el oxígeno del frasco! Si tienes dos frascos de tamaños distintos, compara: ¿en cuál dura más la llama?"] }, at: "Ficha del laboratorio nº 26", m: "cuaderno, lápices de colores", p: ["Dibuja el triángulo del fuego con combustible, calor y oxígeno en cada punta.", "Dibuja la vela antes y después de ser tapada por el frasco.", "Con tu familia, acuerden las reglas de seguridad con el fuego de tu casa y escríbelas."], q: "¿Por qué crees que es tan importante tener un adulto cerca cuando hay fuego?" } },

{ e: "🥣", art: { b: "🥣", s: ["🧲", "⚙️", "💪", "🩸"], c: ["#3A3A4A", "#C2C2D4"] },
pt: { h: "Leo leu a caixa de cereal do café da manhã e encontrou a palavra “ferro” na lista. “Tem metal no meu cereal?”, perguntou, assustado. O vovô pegou um ímã forte e um saquinho com água: “Sim, e é bom para você! Vamos pescar esse ferro?”", t: "Ferro no cereal", f: "O ferro é um mineral que o nosso corpo precisa. Ele ajuda o sangue a levar oxigênio dos pulmões para o corpo inteiro. Por isso, alguns cereais e farinhas recebem pozinhos de ferro bem fininho, chamado de fortificação. Como é ferro de verdade, um ímã forte consegue atrair essas partículas minúsculas!", x: "O nosso sangue é vermelho por causa de uma proteína chamada hemoglobina, que tem ferro no meio dela. É o ferro que segura o oxigênio! Alimentos como feijão, lentilha, carne e folhas verde-escuras também têm ferro.", s: ["Comer frutas com vitamina C, como laranja, ajuda o corpo a aproveitar melhor o ferro dos vegetais.", "O ferro dos alimentos não deixa ninguém “magnético”: a quantidade é minúscula.", "O núcleo da Terra é feito principalmente de ferro."], ex: { t: "Pescando ferro", m: "uma xícara de cereal fortificado com ferro (veja no rótulo), um saco plástico com fecho, água morna, um ímã forte (de neodímio, só com um adulto)", p: ["Coloque o cereal no saco, acrescente água morna, feche e amasse bem até virar uma papa. Espere uns 20 minutos.", "Com um adulto, encoste o ímã forte do lado de fora do saco e balance o saco devagar por um ou dois minutos.", "Vire o saco com o ímã ainda encostado: veja os pontinhos escuros de ferro grudados perto do ímã!"] }, at: "Ficha do laboratório nº 27", m: "caderno, lápis de cor, rótulos de alimentos", p: ["Com um adulto, procure a palavra “ferro” nos rótulos de 3 alimentos da sua casa.", "Desenhe o caminho do oxigênio: pulmão, sangue com ferro e o corpo.", "Faça uma lista de alimentos ricos em ferro de que você gosta."], q: "Que alimento rico em ferro você mais gosta de comer?" },
en: { h: "Leo read the breakfast cereal box and found the word “iron” on the list. “There's metal in my cereal?” he asked, alarmed. Grandpa grabbed a strong magnet and a zip-top bag of water: “Yes, and it's good for you! Shall we go fishing for that iron?”", t: "Iron in cereal", f: "Iron is a mineral our bodies need. It helps blood carry oxygen from the lungs to the whole body. That's why some cereals and flours have very fine iron powder added to them, which is called fortification. Since it's real iron, a strong magnet can pull out these tiny particles!", x: "Our blood is red because of a protein called hemoglobin, which has iron at its center. It's the iron that holds on to oxygen! Foods like beans, lentils, meat and dark green leaves also contain iron.", s: ["Eating fruits with vitamin C, like oranges, helps the body absorb iron from plant foods.", "Iron in food doesn't make anyone “magnetic”: the amount is tiny.", "Earth's core is made mostly of iron."], ex: { t: "Fishing for iron", m: "a cup of iron-fortified cereal (check the label), a zip-top plastic bag, warm water, a strong magnet (neodymium, only with a grown-up)", p: ["Put the cereal in the bag, add warm water, seal it and squish it until it becomes mush. Wait about 20 minutes.", "With a grown-up, hold the strong magnet against the outside of the bag and gently swish the bag around for a minute or two.", "Turn the bag over with the magnet still in place: look for the dark specks of iron gathered near the magnet!"] }, at: "Lab card no. 27", m: "notebook, colored pencils, food labels", p: ["With a grown-up, look for the word “iron” on the labels of 3 foods in your home.", "Draw the path of oxygen: lungs, blood with iron and the body.", "Make a list of iron-rich foods that you like."], q: "Which iron-rich food do you like to eat the most?" },
es: { h: "Leo leyó la caja de cereales del desayuno y encontró la palabra “hierro” en la lista. “¿Hay metal en mis cereales?”, preguntó, asustado. El abuelo agarró un imán fuerte y una bolsita con agua: “¡Sí, y te hace bien! ¿Vamos a pescar ese hierro?”", t: "Hierro en los cereales", f: "El hierro es un mineral que nuestro cuerpo necesita. Ayuda a la sangre a llevar el oxígeno de los pulmones a todo el cuerpo. Por eso, a algunos cereales y harinas se les agrega un polvito de hierro muy fino, lo que se llama fortificación. ¡Como es hierro de verdad, un imán fuerte puede atraer esas partículas diminutas!", x: "¡Nuestra sangre es roja por una proteína llamada hemoglobina, que tiene hierro en el medio! Es el hierro el que sostiene el oxígeno. Alimentos como los porotos, las lentejas, la carne y las hojas verde oscuro también tienen hierro.", s: ["Comer frutas con vitamina C, como la naranja, ayuda al cuerpo a aprovechar mejor el hierro de los vegetales.", "El hierro de los alimentos no vuelve “magnético” a nadie: la cantidad es diminuta.", "El núcleo de la Tierra está hecho principalmente de hierro."], ex: { t: "Pescando hierro", m: "una taza de cereales fortificados con hierro (fíjate en la etiqueta), una bolsa plástica con cierre, agua tibia, un imán fuerte (de neodimio, solo con un adulto)", p: ["Pon los cereales en la bolsa, agrega agua tibia, ciérrala y aplástala bien hasta que sea una papilla. Espera unos 20 minutos.", "Con un adulto, apoya el imán fuerte del lado de afuera de la bolsa y mueve la bolsa despacio uno o dos minutos.", "Da vuelta la bolsa con el imán todavía apoyado: ¡mira los puntitos oscuros de hierro juntos cerca del imán!"] }, at: "Ficha del laboratorio nº 27", m: "cuaderno, lápices de colores, etiquetas de alimentos", p: ["Con un adulto, busca la palabra “hierro” en las etiquetas de 3 alimentos de tu casa.", "Dibuja el camino del oxígeno: pulmón, sangre con hierro y el cuerpo.", "Haz una lista de alimentos ricos en hierro que te gusten."], q: "¿Qué alimento rico en hierro es el que más te gusta comer?" } },

{ e: "🥔", art: { b: "🥔", s: ["🧂", "💧", "🔄", "🥒"], c: ["#5A4A2A", "#E0C88A"] },
pt: { h: "O vovô cortou duas fatias de batata iguaizinhas. Colocou uma num copo de água pura e a outra num copo de água bem salgada. “Daqui a meia hora, uma vai estar dura e a outra mole como borracha”, disse ele. “Adivinhem qual!” Leo apostou na salgada para ficar dura. Será que acertou?", t: "Osmose: a água que viaja", f: "As células das plantas são como saquinhos cheios de água, com uma pele que deixa a água passar. A água tende a se mover do lugar com menos sal para o lugar com mais sal, tentando equilibrar. Na água salgada, a água sai de dentro da batata, e ela murcha e fica mole. Na água pura, a água entra na batata, e ela fica firme e durinha. Esse movimento se chama osmose.", x: "É por osmose que as raízes das plantas bebem água da terra! E é também por isso que os pepinos viram picles: a salmoura puxa a água de dentro deles. As alfaces murchas podem até ficar crocantes de novo se ficarem um tempo em água fria.", s: ["Salgar a berinjela ou o pepino antes de cozinhar ajuda a tirar a água deles.", "As uvas-passas são uvas que perderam água.", "O nosso corpo também usa a osmose para controlar a água nas células."], ex: { t: "A batata que murcha", m: "uma batata cortada em fatias iguais por um adulto, 2 copos, água, 3 colheres de sal", p: ["Encha os dois copos com água e misture o sal em apenas um deles.", "Coloque uma fatia de batata em cada copo e espere 30 minutos.", "Tire as fatias e tente dobrá-las: a da água salgada fica mole e dobra, e a da água pura fica firme!"] }, at: "Ficha do laboratório nº 28", m: "caderno, lápis de cor", p: ["Desenhe as duas fatias depois de 30 minutos, com setas mostrando para onde a água foi.", "Desenhe uma célula como um saquinho de água.", "Teste uma folha de alface murcha em água gelada e anote o que aconteceu."], q: "Você acertou qual batata ia ficar mole? O que te surpreendeu?" },
en: { h: "Grandpa cut two identical potato slices. He put one in a glass of plain water and the other in a glass of very salty water. “In half an hour, one will be stiff and the other floppy like rubber,” he said. “Guess which!” Leo bet the salty one would be stiff. Was he right?", t: "Osmosis: water on the move", f: "Plant cells are like little bags full of water, with a skin that lets water pass through. Water tends to move from the place with less salt to the place with more salt, trying to even things out. In salty water, water flows out of the potato, and it shrinks and goes floppy. In plain water, water flows into the potato, and it becomes firm and stiff. This movement is called osmosis.", x: "It's by osmosis that plant roots drink water from the soil! It's also why cucumbers become pickles: the brine pulls water out of them. Wilted lettuce can even turn crisp again if it sits in cold water for a while.", s: ["Salting eggplant or cucumber before cooking helps draw water out of it.", "Raisins are grapes that have lost water.", "Our bodies also use osmosis to control the water in our cells."], ex: { t: "The floppy potato", m: "a potato cut into equal slices by a grown-up, 2 glasses, water, 3 spoonfuls of salt", p: ["Fill both glasses with water and stir the salt into just one of them.", "Put a potato slice in each glass and wait 30 minutes.", "Take out the slices and try bending them: the one from the salty water is floppy and bends, and the one from plain water stays firm!"] }, at: "Lab card no. 28", m: "notebook, colored pencils", p: ["Draw both slices after 30 minutes, with arrows showing where the water went.", "Draw a cell as a little bag of water.", "Test a wilted lettuce leaf in ice water and write down what happened."], q: "Did you guess which potato would go floppy? What surprised you?" },
es: { h: "El abuelo cortó dos rodajas de papa igualitas. Puso una en un vaso de agua pura y la otra en un vaso de agua muy salada. “Dentro de media hora, una va a estar dura y la otra blanda como goma”, dijo. “¡Adivinen cuál!” Leo apostó a que la salada iba a quedar dura. ¿Habrá acertado?", t: "Ósmosis: el agua que viaja", f: "Las células de las plantas son como bolsitas llenas de agua, con una piel que deja pasar el agua. El agua tiende a moverse del lugar con menos sal al lugar con más sal, tratando de equilibrar. En el agua salada, el agua sale de adentro de la papa, y esta se marchita y queda blanda. En el agua pura, el agua entra en la papa, y queda firme y durita. Ese movimiento se llama ósmosis.", x: "¡Es por ósmosis que las raíces de las plantas toman agua de la tierra! Y por eso también los pepinos se convierten en pepinillos: la salmuera les saca el agua de adentro. Las lechugas marchitas pueden volver a estar crocantes si se dejan un rato en agua fría.", s: ["Salar la berenjena o el pepino antes de cocinarlos ayuda a sacarles el agua.", "Las pasas de uva son uvas que perdieron agua.", "Nuestro cuerpo también usa la ósmosis para controlar el agua de las células."], ex: { t: "La papa que se ablanda", m: "una papa cortada en rodajas iguales por un adulto, 2 vasos, agua, 3 cucharadas de sal", p: ["Llena los dos vasos con agua y mezcla la sal en uno solo de ellos.", "Pon una rodaja de papa en cada vaso y espera 30 minutos.", "Saca las rodajas e intenta doblarlas: ¡la del agua salada queda blanda y se dobla, y la del agua pura queda firme!"] }, at: "Ficha del laboratorio nº 28", m: "cuaderno, lápices de colores", p: ["Dibuja las dos rodajas después de 30 minutos, con flechas que muestren hacia dónde fue el agua.", "Dibuja una célula como una bolsita de agua.", "Prueba una hoja de lechuga marchita en agua helada y anota qué pasó."], q: "¿Adivinaste qué papa se iba a ablandar? ¿Qué te sorprendió?" } },

{ e: "👩‍🔬", art: { b: "👩‍🔬", s: ["⚖️", "✨", "📚", "🏅"], c: ["#2B2D6E", "#C2A0F0"] },
pt: { h: "Numa tarde chuvosa, o vovô abriu um livro grande de ciências cheio de retratos antigos. “Toda a química que vocês fizeram neste mês foi descoberta por pessoas curiosas, como vocês”, disse. “Hoje vou apresentar duas delas: um francês que pesava tudo e uma polonesa que descobriu brilhos invisíveis.”", t: "Grandes químicos da história", f: "Antoine Lavoisier, na França dos anos 1700, fez experimentos pesando tudo com muito cuidado e mostrou que, numa reação química, nada some e nada aparece do nada: os materiais só se transformam. Ele também ajudou a entender o papel do oxigênio no fogo. Marie Curie, nascida na Polônia, estudou a radioatividade e descobriu dois elementos novos: o polônio e o rádio.", x: "Marie Curie foi a primeira mulher a ganhar um Prêmio Nobel e a primeira pessoa a ganhar dois, um de Física, em 1903, e um de Química, em 1911! Ela deu o nome de polônio a um dos elementos que descobriu em homenagem ao seu país, a Polônia.", s: ["Lavoisier trabalhava junto com Marie-Anne Paulze Lavoisier, que desenhava os experimentos e traduzia textos científicos.", "A filha de Marie Curie, Irène, também ganhou um Prêmio Nobel de Química.", "Hoje existem 118 elementos químicos conhecidos, organizados na tabela periódica."], at: "Ficha do laboratório nº 29", m: "caderno, lápis de cor, papel", p: ["Desenhe o retrato de Lavoisier com sua balança e o de Marie Curie no laboratório.", "Escreva a frase de Lavoisier com suas palavras: “Na química, nada se perde, tudo se transforma”.", "Invente um elemento químico novo: dê um nome, um símbolo e desenhe como ele seria."], q: "Se você descobrisse um elemento novo, em homenagem a quem ou a que lugar daria o nome?" },
en: { h: "On a rainy afternoon, Grandpa opened a big science book full of old portraits. “All the chemistry you've done this month was discovered by curious people, just like you,” he said. “Today I'll introduce you to two of them: a Frenchman who weighed everything and a Polish woman who discovered invisible glows.”", t: "Great chemists in history", f: "Antoine Lavoisier, in 1700s France, did experiments weighing everything very carefully and showed that in a chemical reaction nothing disappears and nothing appears out of nowhere: materials only transform. He also helped explain the role of oxygen in fire. Marie Curie, born in Poland, studied radioactivity and discovered two new elements: polonium and radium.", x: "Marie Curie was the first woman to win a Nobel Prize and the first person to win two, one in Physics in 1903 and one in Chemistry in 1911! She named one of the elements she discovered polonium in honor of her home country, Poland.", s: ["Lavoisier worked with Marie-Anne Paulze Lavoisier, who drew the experiments and translated scientific texts.", "Marie Curie's daughter, Irène, also won a Nobel Prize in Chemistry.", "Today there are 118 known chemical elements, arranged in the periodic table."], at: "Lab card no. 29", m: "notebook, colored pencils, paper", p: ["Draw a portrait of Lavoisier with his scale and of Marie Curie in her lab.", "Write Lavoisier's idea in your own words: “In chemistry, nothing is lost; everything is transformed.”", "Invent a new chemical element: give it a name and a symbol, and draw what it would look like."], q: "If you discovered a new element, who or what place would you name it after?" },
es: { h: "Una tarde de lluvia, el abuelo abrió un libro grande de ciencias lleno de retratos antiguos. “Toda la química que hicieron este mes la descubrieron personas curiosas, como ustedes”, dijo. “Hoy les voy a presentar a dos de ellas: un francés que pesaba todo y una polaca que descubrió brillos invisibles.”", t: "Grandes químicos de la historia", f: "Antoine Lavoisier, en la Francia de los años 1700, hizo experimentos pesando todo con mucho cuidado y mostró que, en una reacción química, nada desaparece y nada aparece de la nada: los materiales solo se transforman. También ayudó a entender el papel del oxígeno en el fuego. Marie Curie, nacida en Polonia, estudió la radiactividad y descubrió dos elementos nuevos: el polonio y el radio.", x: "¡Marie Curie fue la primera mujer en ganar un Premio Nobel y la primera persona en ganar dos, uno de Física, en 1903, y uno de Química, en 1911! Le puso el nombre de polonio a uno de los elementos que descubrió en homenaje a su país, Polonia.", s: ["Lavoisier trabajaba junto con Marie-Anne Paulze Lavoisier, que dibujaba los experimentos y traducía textos científicos.", "La hija de Marie Curie, Irène, también ganó un Premio Nobel de Química.", "Hoy se conocen 118 elementos químicos, ordenados en la tabla periódica."], at: "Ficha del laboratorio nº 29", m: "cuaderno, lápices de colores, papel", p: ["Dibuja el retrato de Lavoisier con su balanza y el de Marie Curie en el laboratorio.", "Escribe la idea de Lavoisier con tus palabras: “En la química, nada se pierde, todo se transforma”.", "Inventa un elemento químico nuevo: ponle un nombre, un símbolo y dibuja cómo sería."], q: "Si descubrieras un elemento nuevo, ¿en homenaje a quién o a qué lugar le pondrías el nombre?" } },

{ e: "🎉", art: { b: "🧪", s: ["⭐", "🌈", "🎉", "🏅"], c: ["#2B2D6E", "#F0C83A"] },
pt: { h: "Chegou o último dia do Laboratório da Cozinha! Nina e Leo prepararam um grande show de química para a família: leite mágico, mensagem secreta, repolho que muda de cor e um gêiser no quintal. A Pipoca assistiu tudo do alto da geladeira. No final, o vovô entregou um certificado: “Vocês agora são químicos mirins de verdade!”", t: "O grande show de química", f: "Neste mês, vocês descobriram que a química está em todo lugar: nas misturas, nas separações, nas reações que soltam gás, nas cores que mudam, nos alimentos que cozinham e até dentro do nosso corpo. Química é a ciência das transformações, e a cozinha é um dos melhores laboratórios do mundo!", x: "Os químicos e as químicas de hoje criam remédios, tecidos, tintas, alimentos mais seguros e materiais que ajudam a cuidar do planeta. E tudo começa com as mesmas perguntas que vocês fizeram: “O que acontece se eu misturar isso?” e “Por quê?”.", s: ["Um bom cientista sempre anota o que fez e o que observou.", "Errar faz parte da ciência: muitos experimentos dão errado antes de dar certo.", "A segurança vem sempre em primeiro lugar: óculos, adultos por perto e nada de provar o que não é comida."], at: "Ficha do laboratório nº 30", m: "caderno, lápis de cor, materiais dos seus experimentos favoritos", p: ["Escolha seus 3 experimentos favoritos do mês e apresente um show de química para a família.", "Faça um cartaz com o título “Meu Laboratório da Cozinha” e desenhe as suas descobertas.", "Escreva: “Hoje eu sei que…” e complete com 5 coisas que você aprendeu."], q: "Qual foi o seu experimento favorito deste mês e por quê?" },
en: { h: "The last day of the Kitchen Lab had arrived! Nina and Leo put on a big chemistry show for the family: magic milk, a secret message, color-changing cabbage and a geyser in the yard. Popcorn watched it all from the top of the fridge. At the end, Grandpa handed out a certificate: “You're real junior chemists now!”", t: "The great chemistry show", f: "This month, you discovered that chemistry is everywhere: in mixtures, in separating things, in reactions that release gas, in colors that change, in food that cooks and even inside our bodies. Chemistry is the science of transformations, and the kitchen is one of the best labs in the world!", x: "Today's chemists create medicines, fabrics, paints, safer foods and materials that help take care of the planet. And it all starts with the same questions you asked: “What happens if I mix this?” and “Why?”", s: ["A good scientist always writes down what they did and what they observed.", "Mistakes are part of science: many experiments fail before they work.", "Safety always comes first: goggles, grown-ups nearby and never tasting anything that isn't food."], at: "Lab card no. 30", m: "notebook, colored pencils, materials from your favorite experiments", p: ["Pick your 3 favorite experiments of the month and put on a chemistry show for your family.", "Make a poster titled “My Kitchen Lab” and draw your discoveries.", "Write: “Now I know that…” and finish it with 5 things you learned."], q: "What was your favorite experiment this month and why?" },
es: { h: "¡Llegó el último día del Laboratorio de la Cocina! Nina y Leo prepararon un gran show de química para la familia: leche mágica, mensaje secreto, repollo que cambia de color y un géiser en el patio. Palomita miró todo desde arriba de la heladera. Al final, el abuelo entregó un certificado: “¡Ahora son químicos junior de verdad!”", t: "El gran show de química", f: "Este mes, descubrieron que la química está en todas partes: en las mezclas, en las separaciones, en las reacciones que sueltan gas, en los colores que cambian, en los alimentos que se cocinan y hasta dentro de nuestro cuerpo. ¡La química es la ciencia de las transformaciones, y la cocina es uno de los mejores laboratorios del mundo!", x: "Los químicos y las químicas de hoy crean medicamentos, telas, pinturas, alimentos más seguros y materiales que ayudan a cuidar el planeta. Y todo empieza con las mismas preguntas que ustedes se hicieron: “¿Qué pasa si mezclo esto?” y “¿Por qué?”.", s: ["Un buen científico siempre anota lo que hizo y lo que observó.", "Equivocarse es parte de la ciencia: muchos experimentos salen mal antes de salir bien.", "La seguridad siempre va primero: anteojos, adultos cerca y nunca probar lo que no es comida."], at: "Ficha del laboratorio nº 30", m: "cuaderno, lápices de colores, materiales de tus experimentos favoritos", p: ["Elige tus 3 experimentos favoritos del mes y presenta un show de química para tu familia.", "Haz un cartel con el título “Mi Laboratorio de la Cocina” y dibuja tus descubrimientos.", "Escribe: “Hoy sé que…” y complétalo con 5 cosas que aprendiste."], q: "¿Cuál fue tu experimento favorito de este mes y por qué?" } },
];
